def dedupe_by_last(records):
    seen = {}
    positions = []
    for idx, record in enumerate(records):
        key = record[0]
        if key not in seen:
            positions.append(idx)
        seen[key] = record
    ordered = [seen[key] for key in [records[i][0] for i in positions]]
    return ordered

